@push('scripts')<script>document.addEventListener('DOMContentLoaded',function(){const modal=document.getElementById('driverFilterModal'),search=document.getElementById('driverModalSearch'),rows=document.getElementById('driverModalRows'),target=document.getElementById('driverFilter'),label=document.getElementById('driverFilterLabel'),reset=document.getElementById('driverFilterReset');if(!modal||!search||!rows||!target||!label)return;modal.addEventListener('shown.bs.modal',function(){search.value='';search.focus();rows.querySelectorAll('tr').forEach(row=>row.classList.remove('d-none'))});search.addEventListener('input',function(){const q=search.value.toLowerCase().trim();rows.querySelectorAll('tr').forEach(row=>row.classList.toggle('d-none',!row.dataset.search.includes(q)))});modal.addEventListener('click',function(event){const button=event.target.closest('.choose-driver');if(!button)return;target.value=button.dataset.id||'';label.value=button.dataset.label||'';bootstrap.Modal.getInstance(modal)?.hide()});reset?.addEventListener('click',function(){target.value='';label.value=''})});</script>@endpush
